import{b as a,O as e,g as r,j as d}from"./chunks/framework.DcaUmd3X.js";const u=JSON.parse('{"title":"核心元件详解","description":"","frontmatter":{},"headers":[],"relativePath":"performance/jmeter/components/index.md","filePath":"性能测试/1.Jmeter/04.核心元件详解.md","lastUpdated":1781755252000}'),s={name:"performance/jmeter/components/index.md"};function o(n,t,i,l,h,p){return e(),r("div",null,[...t[0]||(t[0]=[d(`<h1 id="核心元件详解" tabindex="-1">核心元件详解 <a class="header-anchor" href="#核心元件详解" aria-label="Permalink to &quot;核心元件详解&quot;">​</a></h1><blockquote><p>逐一拆解 JMeter 的八类元件，搞懂每种元件干什么、怎么选、什么时候用。</p></blockquote><p>回顾第一章的口诀——<strong>配前定，取后断听</strong>。八类元件按执行顺序排列，这一章也按这个顺序来讲。</p><hr><h2 id="线程组-thread-group-—-多少个用户-怎么来" tabindex="-1">线程组 (Thread Group) — &quot;多少个用户，怎么来&quot; <a class="header-anchor" href="#线程组-thread-group-—-多少个用户-怎么来" aria-label="Permalink to &quot;线程组 (Thread Group) — &quot;多少个用户，怎么来&quot;&quot;">​</a></h2><p>线程组定义了压测的<strong>用户模型</strong>：多少人、怎么启动、跑多久。</p><h3 id="标准线程组-thread-group" tabindex="-1">标准线程组 (Thread Group) <a class="header-anchor" href="#标准线程组-thread-group" aria-label="Permalink to &quot;标准线程组 (Thread Group)&quot;">​</a></h3><p>右键 Test Plan → 添加 → 线程（用户）→ 线程组</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>怎么设</th></tr></thead><tbody><tr><td>线程数</td><td>并发用户数</td><td>从小到大递进，别上来就填 1000</td></tr><tr><td>Ramp-Up 时间（秒）</td><td>启动全部线程的耗时</td><td>建议 = 线程数 ÷ 5，比如 50 线程设 10 秒</td></tr><tr><td>循环次数</td><td>每个线程跑几轮</td><td>调试填 1~3；正式压测勾&quot;永远&quot;+ 设持续时间</td></tr><tr><td>调度器 → 持续时间</td><td>总运行时长</td><td>基准测试 60 秒，稳定性测试 10~30 分钟</td></tr></tbody></table><h3 id="setup-teardown-线程组-setup-teardown-thread-group" tabindex="-1">setUp / tearDown 线程组 (setUp / tearDown Thread Group) <a class="header-anchor" href="#setup-teardown-线程组-setup-teardown-thread-group" aria-label="Permalink to &quot;setUp / tearDown 线程组 (setUp / tearDown Thread Group)&quot;">​</a></h3><p>这两个是&quot;辅助线程组&quot;，不参与主体压测统计：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setUp 线程组 (setUp Thread Group)    → 最先执行，只跑一次。用来做登录、准备测试数据</span></span>
<span class="line"><span>  普通线程组                          → 主体压测</span></span>
<span class="line"><span>tearDown 线程组 (tearDown Thread Group) → 最后执行，只跑一次。用来做清理、登出</span></span></code></pre></div><blockquote><p>就算普通线程组报错停止了，tearDown 也会执行，保证清理逻辑不会漏。</p></blockquote><h3 id="插件线程组-custom-thread-groups" tabindex="-1">插件线程组 (Custom Thread Groups) <a class="header-anchor" href="#插件线程组-custom-thread-groups" aria-label="Permalink to &quot;插件线程组 (Custom Thread Groups)&quot;">​</a></h3><p>JMeter 5.5 以上已内置 Plugins Manager，直接装插件就行：</p><blockquote><p>菜单栏 → <strong>Options</strong> → <strong>Plugins Manager</strong> → Available Plugins → 搜索 <strong>Custom Thread Groups</strong> → 勾选 → <strong>Apply Changes and Restart</strong></p></blockquote><p>装完后再右键线程组就能看到这些新类型：</p><table tabindex="0"><thead><tr><th>类型</th><th>一句话</th><th>典型场景</th></tr></thead><tbody><tr><td><strong>Concurrency Thread Group</strong></td><td>阶梯式加压</td><td>&quot;从 10 人每分钟加 10 人，一直加到 100，看系统什么时候崩&quot;</td></tr><tr><td><strong>Ultimate Thread Group</strong></td><td>多波次浪涌</td><td>&quot;模拟秒杀：第 1 波 100 人、隔 30 秒第 2 波 200 人、再隔 30 秒第 3 波 500 人&quot;</td></tr><tr><td><strong>Arrivals Thread Group</strong></td><td>控制每秒请求数</td><td>&quot;不管多少人，每秒稳定发 100 个请求&quot;</td></tr></tbody></table><blockquote><p>日常压测用标准线程组就够了。需要阶梯加压用 Concurrency TG，需要控 TPS 用 Arrivals TG。</p></blockquote><hr><h2 id="取样器-sampler-—-发什么请求" tabindex="-1">取样器 (Sampler) — &quot;发什么请求&quot; <a class="header-anchor" href="#取样器-sampler-—-发什么请求" aria-label="Permalink to &quot;取样器 (Sampler) — &quot;发什么请求&quot;&quot;">​</a></h2><p>取样器是压测的<strong>核心动作</strong>——真正发请求的就是它。</p><h3 id="http-请求-http-request-使用频率-90" tabindex="-1">HTTP 请求 (HTTP Request)（使用频率 90%+） <a class="header-anchor" href="#http-请求-http-request-使用频率-90" aria-label="Permalink to &quot;HTTP 请求 (HTTP Request)（使用频率 90%+）&quot;">​</a></h3><p>一个 HTTP 请求由五要素组成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>协议 + 服务器 + 端口 + 方法 + 路径 = 一个完整的请求</span></span>
<span class="line"><span>http   localhost  8080   POST   /api/login</span></span></code></pre></div><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>协议</td><td>http 或 https</td><td>https</td></tr><tr><td>服务器名称或 IP</td><td>目标主机</td><td>api.example.com</td></tr><tr><td>端口号</td><td>服务端口</td><td>443</td></tr><tr><td>HTTP 方法</td><td>GET / POST / PUT / DELETE</td><td>POST</td></tr><tr><td>路径</td><td>接口路径</td><td>/api/login</td></tr><tr><td>消息体数据</td><td>POST/PUT 时传的 JSON</td><td><code>{&quot;username&quot;:&quot;admin&quot;}</code></td></tr><tr><td>参数</td><td>GET 请求的 Query String</td><td><code>?page=1&amp;size=10</code></td></tr></tbody></table><blockquote><p><strong>技巧</strong>：把协议、服务器、端口抽到「HTTP 请求默认值」里，每个请求只写方法和路径，少敲很多重复内容。</p></blockquote><h3 id="其他取样器" tabindex="-1">其他取样器 <a class="header-anchor" href="#其他取样器" aria-label="Permalink to &quot;其他取样器&quot;">​</a></h3><table tabindex="0"><thead><tr><th>取样器</th><th>什么时候用</th></tr></thead><tbody><tr><td><strong>JDBC 请求 (JDBC Request)</strong></td><td>直接对数据库执行 SQL，测数据库性能</td></tr><tr><td><strong>JSR223 取样器 (JSR223 Sampler)</strong></td><td>写 Groovy 脚本自定义请求逻辑</td></tr><tr><td><strong>TCP 取样器 (TCP Sampler)</strong></td><td>测自定义 TCP 协议</td></tr><tr><td><strong>WebSocket</strong>（插件）</td><td>测实时通信应用（聊天、推送）</td></tr><tr><td><strong>OS 进程取样器 (OS Process Sampler)</strong></td><td>调用系统命令</td></tr></tbody></table><blockquote><p>90% 的场景只用 HTTP 请求和 JDBC 请求，其他的用到再查。</p></blockquote><hr><h2 id="配置元件-config-element-—-一次配置-到处复用" tabindex="-1">配置元件 (Config Element) — &quot;一次配置，到处复用&quot; <a class="header-anchor" href="#配置元件-config-element-—-一次配置-到处复用" aria-label="Permalink to &quot;配置元件 (Config Element) — &quot;一次配置，到处复用&quot;&quot;">​</a></h2><blockquote><p>口诀：<strong>默头管 C 数</strong>——默认值、请求头管理器、Cookie 管理器、CSV 数据、计数器。</p></blockquote><h3 id="http-请求默认值-http-request-defaults" tabindex="-1">HTTP 请求默认值 (HTTP Request Defaults) <a class="header-anchor" href="#http-请求默认值-http-request-defaults" aria-label="Permalink to &quot;HTTP 请求默认值 (HTTP Request Defaults)&quot;">​</a></h3><p>把公共的协议、服务器、端口写在这里，同作用域下的所有 HTTP 请求自动继承：</p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>协议</td><td>https</td></tr><tr><td>服务器名称或 IP</td><td>api.example.com</td></tr><tr><td>端口号</td><td>443</td></tr></tbody></table><p>之后每个 HTTP 请求只需填<strong>方法</strong>和<strong>路径</strong>，三个字段留空即可。</p><h3 id="http-信息头管理器-http-header-manager" tabindex="-1">HTTP 信息头管理器 (HTTP Header Manager) <a class="header-anchor" href="#http-信息头管理器-http-header-manager" aria-label="Permalink to &quot;HTTP 信息头管理器 (HTTP Header Manager)&quot;">​</a></h3><p>统一管理请求头。第三章已经用过了——一个设 Content-Type，一个设 Authorization。</p><p>多个 Header Manager 可以共存，JMeter 自动合并。同名头以<strong>离请求最近</strong>的那个为准（近优先）。</p><h3 id="http-cookie-管理器-http-cookie-manager" tabindex="-1">HTTP Cookie 管理器 (HTTP Cookie Manager) <a class="header-anchor" href="#http-cookie-管理器-http-cookie-manager" aria-label="Permalink to &quot;HTTP Cookie 管理器 (HTTP Cookie Manager)&quot;">​</a></h3><p>自动处理 Cookie：服务器返回的 Set-Cookie 自动存储，后续请求自动带上。<strong>每个线程有独立的 Cookie 存储</strong>，模拟不同用户的登录状态。</p><h3 id="csv-数据文件设置-csv-data-set-config-参数化核心" tabindex="-1">CSV 数据文件设置 (CSV Data Set Config)（参数化核心） <a class="header-anchor" href="#csv-数据文件设置-csv-data-set-config-参数化核心" aria-label="Permalink to &quot;CSV 数据文件设置 (CSV Data Set Config)（参数化核心）&quot;">​</a></h3><p>从文件读取测试数据，实现&quot;不同用户用不同账号登录&quot;：</p><div class="language-csv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"># 文件：users.csv</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">username,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">password</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user001,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pass001</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user002,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pass002</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user003,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pass003</span></span></code></pre></div><table tabindex="0"><thead><tr><th>配置项</th><th>值</th><th>说明</th></tr></thead><tbody><tr><td>文件名</td><td>users.csv</td><td>放在 JMeter bin 目录下或写绝对路径</td></tr><tr><td>变量名称</td><td>username,password</td><td>逗号分隔，对应 CSV 的列</td></tr><tr><td>忽略首行</td><td>True</td><td>CSV 第一行是标题就勾上</td></tr><tr><td>遇到 EOF 是否循环</td><td>True</td><td>数据用完了就从头开始</td></tr><tr><td>共享模式</td><td>所有线程</td><td>每个线程取不同行，不重复</td></tr></tbody></table><p>引用方式：<code>\${username}</code>、<code>\${password}</code></p><h3 id="用户定义的变量-user-defined-variables" tabindex="-1">用户定义的变量 (User Defined Variables) <a class="header-anchor" href="#用户定义的变量-user-defined-variables" aria-label="Permalink to &quot;用户定义的变量 (User Defined Variables)&quot;">​</a></h3><p>放全局常量，比如环境地址、版本号。适合<strong>值不变的小数据</strong>。</p><hr><h2 id="后置处理器-post-processor-—-从响应里捞数据" tabindex="-1">后置处理器 (Post-Processor) — &quot;从响应里捞数据&quot; <a class="header-anchor" href="#后置处理器-post-processor-—-从响应里捞数据" aria-label="Permalink to &quot;后置处理器 (Post-Processor) — &quot;从响应里捞数据&quot;&quot;">​</a></h2><blockquote><p>这一步叫<strong>关联（Correlation）</strong>，是压测脚本里最重要的操作。</p></blockquote><h3 id="三种最常用的提取器" tabindex="-1">三种最常用的提取器 <a class="header-anchor" href="#三种最常用的提取器" aria-label="Permalink to &quot;三种最常用的提取器&quot;">​</a></h3><table tabindex="0"><thead><tr><th>提取器</th><th>适合什么响应</th><th>表达式示例</th></tr></thead><tbody><tr><td><strong>JSON 提取器 (JSON Extractor)</strong></td><td>JSON</td><td><code>$.data.token</code></td></tr><tr><td><strong>正则表达式提取器 (Regular Expression Extractor)</strong></td><td>任意文本</td><td><code>token=([a-f0-9]{32})</code></td></tr><tr><td><strong>边界提取器 (Boundary Extractor)</strong></td><td>有明确前后标记</td><td>左 <code>csrf&quot; value=&quot;</code> 右 <code>&quot;</code></td></tr></tbody></table><h3 id="json-提取器-json-extractor-详解" tabindex="-1">JSON 提取器 (JSON Extractor) 详解 <a class="header-anchor" href="#json-提取器-json-extractor-详解" aria-label="Permalink to &quot;JSON 提取器 (JSON Extractor) 详解&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>创建的变量名称</td><td>提取后存到哪个变量</td><td>token</td></tr><tr><td>JSON Path 表达式</td><td>定位要提取的字段</td><td>$.data.token</td></tr><tr><td>默认值</td><td>提取失败时用的兜底值</td><td>NOT_FOUND</td></tr></tbody></table><p><strong>JSON Path 速查</strong>：</p><table tabindex="0"><thead><tr><th>表达式</th><th>取什么</th></tr></thead><tbody><tr><td><code>$.token</code></td><td>根下的 token</td></tr><tr><td><code>$.data.id</code></td><td>data 下的 id</td></tr><tr><td><code>$.items[0].name</code></td><td>items 数组第一项的 name</td></tr><tr><td><code>$.items[*].id</code></td><td>items 数组所有项的 id</td></tr></tbody></table><h3 id="正则表达式提取器-regular-expression-extractor-兜底方案" tabindex="-1">正则表达式提取器 (Regular Expression Extractor)（兜底方案） <a class="header-anchor" href="#正则表达式提取器-regular-expression-extractor-兜底方案" aria-label="Permalink to &quot;正则表达式提取器 (Regular Expression Extractor)（兜底方案）&quot;">​</a></h3><p>当响应不是 JSON 时用。比如从 HTML 页面提取隐藏字段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>响应内容：&lt;input type=&quot;hidden&quot; name=&quot;csrf_token&quot; value=&quot;a8f3b2c1e5&quot;&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>正则表达式：name=&quot;csrf_token&quot; value=&quot;([^&quot;]+)&quot;</span></span>
<span class="line"><span>模板：$1$</span></span>
<span class="line"><span>变量名：csrf_token</span></span></code></pre></div><ul><li>括号 <code>()</code> 里的是要提取的内容</li><li><code>$1$</code> 表示取第一个括号的匹配结果</li><li>引用：<code>\${csrf_token}</code></li></ul><h3 id="关联三步走" tabindex="-1">关联三步走 <a class="header-anchor" href="#关联三步走" aria-label="Permalink to &quot;关联三步走&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 找 → 看响应里哪个字段是动态的（token、sessionId）</span></span>
<span class="line"><span>2. 提 → 加对应的提取器，设好表达式和变量名</span></span>
<span class="line"><span>3. 用 → 后续请求里用 \${变量名} 引用</span></span></code></pre></div><hr><h2 id="断言-assertion-—-验证结果对不对" tabindex="-1">断言 (Assertion) — &quot;验证结果对不对&quot; <a class="header-anchor" href="#断言-assertion-—-验证结果对不对" aria-label="Permalink to &quot;断言 (Assertion) — &quot;验证结果对不对&quot;&quot;">​</a></h2><blockquote><p>压测时不仅要看快不快，更要看对不对。全部返回 500 错误还以为系统很快，那就闹笑话了。</p></blockquote><h3 id="最常用的两种" tabindex="-1">最常用的两种 <a class="header-anchor" href="#最常用的两种" aria-label="Permalink to &quot;最常用的两种&quot;">​</a></h3><p><strong>响应断言 (Response Assertion)</strong> — 检查状态码或响应内容</p><table tabindex="0"><thead><tr><th>配置</th><th>值</th><th>含义</th></tr></thead><tbody><tr><td>测试字段</td><td>响应代码</td><td>检查 HTTP 状态码</td></tr><tr><td>模式匹配规则</td><td>相等</td><td>精确匹配</td></tr><tr><td>要测试的模式</td><td>200</td><td>期望返回 200</td></tr></tbody></table><p><strong>持续时间断言 (Duration Assertion)</strong> — 检查响应时间</p><table tabindex="0"><thead><tr><th>配置</th><th>值</th><th>含义</th></tr></thead><tbody><tr><td>持续时间（毫秒）</td><td>3000</td><td>超过 3 秒就标记失败</td></tr></tbody></table><h3 id="断言性能损耗分级" tabindex="-1">断言性能损耗分级 <a class="header-anchor" href="#断言性能损耗分级" aria-label="Permalink to &quot;断言性能损耗分级&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">损耗</th><th>断言类型</th><th>压测建议</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>极低</strong></td><td>持续时间断言 (Duration Assertion)、大小断言 (Size Assertion)</td><td>✅ 放心用</td></tr><tr><td style="text-align:center;"><strong>中</strong></td><td>响应断言 (Response Assertion)（只断言状态码）</td><td>✅ 可以用</td></tr><tr><td style="text-align:center;"><strong>高</strong></td><td>JSON 断言 (JSON Assertion)、XPath 断言 (XPath Assertion)、HTML 断言 (HTML Assertion)</td><td>⚠️ 仅调试时用</td></tr></tbody></table><hr><h2 id="定时器-timer-—-模拟真实用户的停顿" tabindex="-1">定时器 (Timer) — &quot;模拟真实用户的停顿&quot; <a class="header-anchor" href="#定时器-timer-—-模拟真实用户的停顿" aria-label="Permalink to &quot;定时器 (Timer) — &quot;模拟真实用户的停顿&quot;&quot;">​</a></h2><blockquote><p>真实用户不会连续狂点。操作之间有思考时间：看页面、填表单、犹豫。</p></blockquote><p>定时器在<strong>每个请求之前</strong>执行，多个定时器会叠加。</p><table tabindex="0"><thead><tr><th>定时器</th><th>行为</th><th style="text-align:center;">推荐度</th></tr></thead><tbody><tr><td><strong>均匀随机定时器 (Uniform Random Timer)</strong></td><td>在一个范围内随机停顿</td><td style="text-align:center;">⭐⭐⭐⭐⭐</td></tr><tr><td><strong>高斯随机定时器 (Gaussian Random Timer)</strong></td><td>大部分时间停差不多，少数特别快/慢</td><td style="text-align:center;">⭐⭐⭐⭐</td></tr><tr><td><strong>固定定时器 (Constant Timer)</strong></td><td>每次停一样长</td><td style="text-align:center;">⭐（仅调试）</td></tr><tr><td><strong>同步定时器 (Synchronizing Timer)</strong></td><td>等人凑够再一起冲（集合点）</td><td style="text-align:center;">⭐⭐⭐</td></tr><tr><td><strong>常数吞吐量定时器 (Constant Throughput Timer)</strong></td><td>控制每秒发多少请求</td><td style="text-align:center;">⭐⭐⭐</td></tr></tbody></table><h3 id="均匀随机定时器-uniform-random-timer-配置" tabindex="-1">均匀随机定时器 (Uniform Random Timer) 配置 <a class="header-anchor" href="#均匀随机定时器-uniform-random-timer-配置" aria-label="Permalink to &quot;均匀随机定时器 (Uniform Random Timer) 配置&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>随机延迟最大时间：2000 毫秒</span></span>
<span class="line"><span>固定延迟：500 毫秒</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 每次请求前停顿 500ms ~ 2500ms 之间的随机值</span></span></code></pre></div><h3 id="同步定时器-synchronizing-timer-集合点" tabindex="-1">同步定时器 (Synchronizing Timer)（集合点） <a class="header-anchor" href="#同步定时器-synchronizing-timer-集合点" aria-label="Permalink to &quot;同步定时器 (Synchronizing Timer)（集合点）&quot;">​</a></h3><p>秒杀场景的关键——让一批用户同时触发请求：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模拟用户组的数量：50   ← 凑够 50 人就一起放</span></span>
<span class="line"><span>超时时间：5000 毫秒    ← 等了 5 秒人还不够也放</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 制造瞬时并发尖峰</span></span></code></pre></div><hr><h2 id="逻辑控制器-logic-controller-—-控制请求的执行顺序" tabindex="-1">逻辑控制器 (Logic Controller) — &quot;控制请求的执行顺序&quot; <a class="header-anchor" href="#逻辑控制器-logic-controller-—-控制请求的执行顺序" aria-label="Permalink to &quot;逻辑控制器 (Logic Controller) — &quot;控制请求的执行顺序&quot;&quot;">​</a></h2><p>默认情况下请求从上到下依次执行。控制器可以改变这个行为。</p><table tabindex="0"><thead><tr><th>控制器</th><th>一句话</th><th>典型场景</th></tr></thead><tbody><tr><td><strong>简单控制器 (Simple Controller)</strong></td><td>纯分组，没逻辑</td><td>把相关请求放一个文件夹里</td></tr><tr><td><strong>If 控制器 (If Controller)</strong></td><td>条件成立才执行</td><td>&quot;上个请求成功才继续&quot;</td></tr><tr><td><strong>While 控制器 (While Controller)</strong></td><td>循环直到条件不成立</td><td>&quot;一直查状态直到返回&#39;完成&#39;&quot;</td></tr><tr><td><strong>事务控制器 (Transaction Controller)</strong></td><td>多个请求打包计时</td><td>&quot;登录+搜索+下单&quot;算一笔总耗时</td></tr><tr><td><strong>吞吐量控制器 (Throughput Controller)</strong></td><td>按比例分配</td><td>&quot;80% 流量查商品，20% 下单&quot;</td></tr><tr><td><strong>交替控制器 (Interleave Controller)</strong></td><td>子请求轮流执行</td><td>&quot;每人只做一个操作，轮流来&quot;</td></tr></tbody></table><h3 id="事务控制器-transaction-controller-的用法" tabindex="-1">事务控制器 (Transaction Controller) 的用法 <a class="header-anchor" href="#事务控制器-transaction-controller-的用法" aria-label="Permalink to &quot;事务控制器 (Transaction Controller) 的用法&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事务控制器（名称：完整下单）</span></span>
<span class="line"><span>  ├── 登录</span></span>
<span class="line"><span>  ├── 搜索商品</span></span>
<span class="line"><span>  ├── 加购物车</span></span>
<span class="line"><span>  └── 提交订单</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 报告里多一行&quot;完整下单&quot;，显示整个流程端到端耗时</span></span>
<span class="line"><span>→ 四个请求全部成功，事务才算成功</span></span></code></pre></div><hr><h2 id="监听器-listener-—-看结果" tabindex="-1">监听器 (Listener) — &quot;看结果&quot; <a class="header-anchor" href="#监听器-listener-—-看结果" aria-label="Permalink to &quot;监听器 (Listener) — &quot;看结果&quot;&quot;">​</a></h2><table tabindex="0"><thead><tr><th>监听器</th><th>干什么</th><th style="text-align:center;">正式压测</th></tr></thead><tbody><tr><td><strong>察看结果树 (View Results Tree)</strong></td><td>逐个看请求/响应详情</td><td style="text-align:center;">❌ 必须关</td></tr><tr><td><strong>汇总报告 (Summary Report)</strong></td><td>平均、最快、最慢、错误率、吞吐量</td><td style="text-align:center;">✅</td></tr><tr><td><strong>聚合报告 (Aggregate Report)</strong></td><td>额外含中位数、90%/95%/99% 线</td><td style="text-align:center;">✅</td></tr><tr><td><strong>用表格察看结果 (View Results in Table)</strong></td><td>表格形式看每次请求</td><td style="text-align:center;">❌</td></tr><tr><td><strong>图形结果 (Graph Results)</strong></td><td>折线图</td><td style="text-align:center;">❌</td></tr></tbody></table><blockquote><p><strong>铁律</strong>：正式压测只保留汇总报告或聚合报告，其他全关。监听器消耗内存，会让压测结果失真。</p></blockquote><hr><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这一章拆解了八类元件，按执行顺序排列：</p><table tabindex="0"><thead><tr><th>元件</th><th>核心作用</th><th>记忆点</th></tr></thead><tbody><tr><td>线程组 (Thread Group)</td><td>定义用户模型</td><td>标准够用，阶梯用插件</td></tr><tr><td>取样器 (Sampler)</td><td>发请求</td><td>HTTP 请求覆盖 90% 场景</td></tr><tr><td>配置元件 (Config Element)</td><td>复用公共配置</td><td>默头管 C 数</td></tr><tr><td>后置处理器 (Post-Processor)</td><td>提取动态值</td><td>关联三步走：找 → 提 → 用</td></tr><tr><td>断言 (Assertion)</td><td>验证结果</td><td>状态码 + 响应时间就够了</td></tr><tr><td>定时器 (Timer)</td><td>模拟思考时间</td><td>均匀随机最常用</td></tr><tr><td>逻辑控制器 (Logic Controller)</td><td>控制流程</td><td>事务控制器最实用</td></tr><tr><td>监听器 (Listener)</td><td>看结果</td><td>调试开，压测关</td></tr></tbody></table><p>实际工作中 80% 的时间只跟其中四类打交道：<strong>取样器 (Sampler)、配置元件 (Config Element)、后置处理器 (Post-Processor)、监听器 (Listener)</strong>。其他的随用随查。</p>`,99)])])}const g=a(s,[["render",o]]);export{u as __pageData,g as default};
